import sys
from collections import defaultdict

MOD = 998244353

def mod_inv(x):
    return pow(x, MOD - 2, MOD)

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:n + 2]))
    w = list(map(int, data[n + 2:]))

    total_weight = sum(w)
    dp = [0] * (total_weight + 1)
    dp[0] = 1

    for i in range(m):
        new_dp = [0] * (total_weight + 1)
        for j in range(total_weight + 1):
            if dp[j]:
                if j + w[i] <= total_weight:
                    new_dp[j + w[i]] += dp[j]
                if j >= w[i]:
                    new_dp[j - w[i]] += dp[j]
        for j in range(total_weight + 1):
            new_dp[j] %= MOD
        dp = new_dp

    result = []
    for i in range(n):
        like = a[i]
        weight = w[i]
        if like == 0:
            weight = -weight
        numerator = dp[weight]
        denominator = dp[0]
        result.append((numerator * mod_inv(denominator)) % MOD)

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    main()
